import { randomBytes, createHash } from "node:crypto";

/**
 * Identifier generation. Three kinds, deliberately kept apart — conflating them
 * is the most common way this class of system leaks (architecture §5.2).
 *
 *   1. Internal primary keys  — UUIDv7, generated by PostgreSQL. Never exposed.
 *   2. Public references      — 128 bits, base62. Safe in a URL.
 *   3. Human codes            — Crockford base32. Printed on paper, read aloud
 *                               over the phone, typed by a tired parent at 21:00.
 */

/**
 * Crockford's base32 alphabet. Excludes I, L, O and U:
 *   - I and L are indistinguishable from 1 in most typefaces and in handwriting
 *   - O is indistinguishable from 0
 *   - U is excluded to reduce the chance of an accidental obscenity
 *
 * This matters more than it sounds. The code is printed, photocopied, sent home
 * in a schoolbag, and typed on a phone keyboard. Every ambiguous glyph is a
 * support call.
 */
const CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";

const BASE62 =
  "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

/** Bits of entropy in a claim code. 10 symbols x 5 bits. */
export const CLAIM_CODE_SYMBOLS = 10;
export const CLAIM_CODE_BITS = CLAIM_CODE_SYMBOLS * 5;

/**
 * Draw `n` symbols from an alphabet using rejection sampling.
 *
 * Rejection sampling rather than `byte % alphabet.length`, because modulo
 * introduces a small bias toward the start of the alphabet. At 50 bits the
 * practical difference is negligible, but "negligible bias in the credential
 * that protects photographs of children" is not a sentence worth writing.
 */
function drawSymbols(alphabet: string, n: number): string {
  const len = alphabet.length;
  // Largest multiple of len that fits in a byte; values above it are rejected.
  const limit = Math.floor(256 / len) * len;
  let out = "";
  while (out.length < n) {
    const buf = randomBytes(Math.max(16, (n - out.length) * 2));
    for (const byte of buf) {
      if (byte >= limit) continue;
      out += alphabet[byte % len];
      if (out.length === n) break;
    }
  }
  return out;
}

/**
 * A one-time claim code. ~50 bits of entropy.
 *
 * With per-IP rate limiting at five attempts a minute, brute force is not a
 * threat model, it is a rounding error (§6.2). The grouping is for legibility
 * on paper and is stripped on input.
 */
export function generateClaimCode(): { plain: string; grouped: string; hint: string } {
  const plain = drawSymbols(CROCKFORD, CLAIM_CODE_SYMBOLS);
  return {
    plain,
    grouped: `${plain.slice(0, 4)}-${plain.slice(4, 7)}-${plain.slice(7, 10)}`,
    // Kept in the database for the support conversation ("...ends in K7P?").
    // Three symbols leaves ~35 bits, which is still far beyond guessable.
    hint: plain.slice(-3),
  };
}

/**
 * Normalise a code as typed by a human.
 *
 * Crockford's decoding rules: case-insensitive, and the ambiguous glyphs map
 * back to what the reader almost certainly meant. A parent who types "l" where
 * the slip prints "1" gets in, rather than getting an error they cannot debug.
 */
export function normaliseCode(input: string): string {
  return input
    .toUpperCase()
    .replace(/[\s\-_.]/g, "")
    .replace(/[ILil]/g, "1")
    .replace(/[Oo]/g, "0");
}

export function isWellFormedClaimCode(input: string): boolean {
  const c = normaliseCode(input);
  return c.length === CLAIM_CODE_SYMBOLS && [...c].every((ch) => CROCKFORD.includes(ch));
}

/**
 * Order number: prefixed, grouped, and drawn from the same alphabet, because
 * order numbers get read aloud over the phone at least as often as claim codes.
 * Not sequential — a sequential order number leaks your volume to competitors
 * and to anyone counting.
 */
export function generateOrderNumber(prefix = "SP"): string {
  const body = drawSymbols(CROCKFORD, 8);
  return `${prefix}-${body.slice(0, 4)}-${body.slice(4, 8)}`;
}

/** 128-bit base62 reference for anything URL-visible. Mirrors app.public_ref(). */
export function generatePublicRef(): string {
  let n = BigInt("0x" + randomBytes(16).toString("hex"));
  let out = "";
  const base = 62n;
  while (n > 0n) {
    out = BASE62[Number(n % base)] + out;
    n /= base;
  }
  return out.padStart(22, "0");
}

/**
 * SHA-256 for opaque session tokens.
 *
 * Session tokens are high-entropy random values, so a fast hash is correct
 * here — there is nothing to brute-force. Claim codes are different: they have
 * only ~50 bits and are chosen from a small alphabet, so they get Argon2id in
 * claim.ts. Using the same primitive for both would be wrong in one direction
 * or the other.
 */
export function hashToken(token: string): Buffer {
  return createHash("sha256").update(token, "utf8").digest();
}

/** Opaque session token. 256 bits, base62. */
export function generateSessionToken(): string {
  return randomBytes(32).toString("base64url");
}
